);}add_action( 'init', 'pandastudio_framework_gutenberg_sidebar_register' );function pandastudio_framework_gutenberg_sidebar_enqueue() {$modified_posttype_and_meta = get_posttype_and_meta_json_by_RestAPI();$meta_page = $modified_posttype_and_meta['meta'];wp_localize_script('pandastudio-framework-gutenberg-sidebar-js','pandastudio_framework_metas',$meta_page
